export let language='en';
export function setLanguage(next){language=next==='pt'?'pt':'en';document.documentElement.lang=language==='pt'?'pt-BR':'en';try{localStorage.setItem('ares-language',language);}catch{}}
export function t(key,params={}){let value=(language==='pt'?pt:en)[key]??en[key]??key;for(const [name,replacement]of Object.entries(params))value=value.replaceAll('{'+name+'}',String(replacement));return value;}
export function format(n,d=0){return new Intl.NumberFormat(language==='pt'?'pt-BR':'en-US',{minimumFractionDigits:d,maximumFractionDigits:d}).format(n);}
export function translatePage(){document.querySelectorAll('[data-t]').forEach(el=>el.textContent=t(el.dataset.t));document.querySelectorAll('[data-aria]').forEach(el=>el.setAttribute('aria-label',t(el.dataset.aria)));}
